function handleRealmCompanion(npc){const c=COMPANIONS.find(v=>v.id===npc.companionId);if(c)companionDialogue(c)}
function companionCombatSupport(){const c=COMPANIONS.find(v=>v.id===state.companions.active);if(!c||state.frame%84!==0)return;const p=state.player,power=companionPower(c),tactic=state.companions.tactic||"balanced",rank=power.rank;if(c.role==="healer"||tactic==="support"&&c.role!=="mana"&&c.role!=="support"&&c.role!=="guard"){const n=Math.min(p.maxHp-p.hp,3+Math.floor(p.level/10)+rank*2+power.hp+(tactic==="support"?2:0));if(n>0){p.hp+=n;showToast(c.name+" uses Field Medicine · +"+n+" HP");updateUI()}return}if(c.role==="mana"){const n=Math.min(p.maxMp-p.mp,2+rank+power.mp);if(n>0){p.mp+=n;showToast(c.name+" restores "+n+" MP");updateUI()}return}if(c.role==="support"){const hp=Math.min(p.maxHp-p.hp,2+rank+power.hp),mp=Math.min(p.maxMp-p.mp,1+Math.floor(rank/2)+power.mp);if(hp||mp){p.hp+=hp;p.mp+=mp;showToast(c.name+" calls Tidal Renewal · +"+hp+" HP · +"+mp+" MP");updateUI()}return}const target=state.enemies.filter(e=>e.alive&&Math.abs(e.x-p.x)+Math.abs(e.y-p.y)<=5).sort((a,b)=>(Math.abs(a.x-p.x)+Math.abs(a.y-p.y))-(Math.abs(b.x-p.x)+Math.abs(b.y-p.y)))[0];if(!target)return;const base=4+Math.floor(p.level*.8)+power.attack+rank*2,damage=(c.role==="heavy"?base+5:c.role==="swift"?base+3:c.role==="arcane"?base+2:base+1)+(tactic==="aggressive"?3:0);damageEnemy(target,damage,true,c.name)}

