function tileAt(x,y){if(x<0||y<0||x>=MAP_W||y>=MAP_H)return 2;return state.grid[y][x]}
function blocked(x,y){return tileAt(x,y)===2||state.npcs.some(n=>n.x===x&&n.y===y)}
function applyExpansionHazard(x,y){if(EXP_DUNGEONS[state.region]===state.area&&tileAt(x,y)===1){state.player.hp=Math.max(1,state.player.hp-4);showToast("Dungeon hazard! -4 HP.");updateUI()}}
