state.npcs.forEach(n=>{let sx=(n.x-camX)*TILE,sy=(n.y-camY)*TILE;if(sx>-TILE&&sy>-TILE&&sx<canvas.width&&sy<canvas.height){drawCharacter(n.x-camX,n.y-camY,n.color,"down");ctx.fillStyle="#17231a";ctx.fillRect(sx-13,sy-12,58,10);ctx.fillStyle="#fff1c9";ctx.font="8px monospace";ctx.fillText(n.name,sx-10,sy-5);if(["expDungeonGate","expDungeonExit","expDungeonRune","switch","depthSwitch","coreSwitch","secretCache","depthCache"].includes(n.kind)){ctx.fillStyle="#f3ca69";ctx.font="bold 11px monospace";ctx.fillText(n.kind==="expDungeonGate"?"D":"◆",sx+25,sy-14)}}});
state.enemies.forEach(e=>{if(!e.alive)return;let sx=(e.x-camX)*TILE,sy=(e.y-camY)*TILE;if(sx>-TILE&&sy>-TILE&&sx<canvas.width&&sy<canvas.height){recordEnemySeen(e);if(e.boss){ctx.fillStyle="#30231f";ctx.fillRect(sx+1,sy+1,30,30);ctx.fillStyle=e.hit>0?"#f3ca69":e.telegraph?"#f2a84b":e.color;ctx.fillRect(sx+4,sy+5,24,23);ctx.fillStyle="#e8c77b";ctx.fillRect(sx+3,sy+2,6,6);ctx.fillRect(sx+23,sy+2,6,6);ctx.fillStyle="#241c1a";ctx.fillRect(sx+9,sy+12,4,4);ctx.fillRect(sx+20,sy+12,4,4);ctx.fillStyle="#f4d18a";ctx.fillRect(sx+12,sy+21,8,3);if(e.telegraph){ctx.fillStyle="#fff0b5";ctx.font="bold 14px monospace";ctx.fillText("!",sx+13,sy-5)}}else{ctx.fillStyle="#17231a";ctx.fillRect(sx+5,sy+5,22,22);ctx.fillStyle=e.hit>0?"#fff0b5":e.color;ctx.fillRect(sx+7,sy+7,18,17);ctx.fillStyle="#17231a";ctx.fillRect(sx+10,sy+12,3,3);ctx.fillRect(sx+19,sy+12,3,3);ctx.fillRect(sx+12,sy+19,8,2)}if(e.hp<e.maxHp){ctx.fillStyle="#291c1b";ctx.fillRect(sx+2,sy-3,e.boss?28:26,4);ctx.fillStyle=e.boss?"#f3ca69":"#d76c60";ctx.fillRect(sx+2,sy-3,(e.boss?28:26)*e.hp/e.maxHp,4)}}});
drawQuestMarker(camX,camY);
drawCharacter(p.x-camX,p.y-camY,"#e7c18a",p.dir,true);drawCompanionFollower(camX,camY);if(state.attackFx>0){const hx=(p.x-camX)*TILE+16,hy=(p.y-camY)*TILE+16,offset=state.attackFxStrong?30:22;ctx.save();ctx.globalAlpha=Math.min(1,state.attackFx/8);ctx.strokeStyle=state.attackFxStrong?"#f3ca69":"#f5efd9";ctx.lineWidth=state.attackFxStrong?5:3;ctx.beginPath();if(p.dir==="right"){ctx.moveTo(hx+offset,hy-18);ctx.lineTo(hx+offset+8,hy);ctx.lineTo(hx+offset,hy+18)}else if(p.dir==="left"){ctx.moveTo(hx-offset,hy-18);ctx.lineTo(hx-offset-8,hy);ctx.lineTo(hx-offset,hy+18)}else if(p.dir==="up"){ctx.moveTo(hx-18,hy-offset);ctx.lineTo(hx,hy-offset-8);ctx.lineTo(hx+18,hy-offset)}else{ctx.moveTo(hx-18,hy+offset);ctx.lineTo(hx,hy+offset+8);ctx.lineTo(hx+18,hy+offset)}ctx.stroke();ctx.restore()}
ctx.fillStyle="#fff0b5";ctx.font="10px monospace";ctx.fillText("✦", (p.x-camX)*TILE+13,(p.y-camY)*TILE-3);
